"""Recognize the blue YOU GOT reward screen without authorizing lobby clicks."""
import base64
import cv2
import numpy as np
_HEADER = cv2.imdecode(np.frombuffer(base64.b64decode(''), np.uint8), cv2.IMREAD_COLOR)
_HEADER = cv2.cvtColor(_HEADER, cv2.COLOR_BGR2RGB)

def is_reward_received(frame):
    from seasonal_rewards import xp_doubler_reward, points_reward, gadget_reward, credits_reward
    from reward_receipts import bling_receipt, locked_skin_receipt
    if bling_receipt(frame) or locked_skin_receipt(frame):
        return True
    if xp_doubler_reward(frame) or points_reward(frame) or gadget_reward(frame) or credits_reward(frame):
        return True
    if frame is None or frame.ndim != 3 or frame.shape[2] != 3:
        return False
    image = cv2.resize(frame, (678, 386), interpolation=cv2.INTER_AREA)
    # A title on the blue reward background; exclude the thumbnail and label.
    background = image[280:370, 30:648]
    blue = (background[:,:,2] > background[:,:,0] * 1.35) & (background[:,:,2] > background[:,:,1] * 1.2)
    if np.mean(blue) < .90:
        return False
    crop = image[55:120, 240:440]
    score = cv2.minMaxLoc(cv2.matchTemplate(crop, _HEADER, cv2.TM_CCOEFF_NORMED))[1]
    return bool(score >= .90)
